window.LANTERN_VIDEOS = [{"id":"elephants-dream","type":"video","title":"Elephants Dream","creator":"Blender Foundation","year":2006,"level":"B1","durationSeconds":654,"genre":"scifi","summaryTr":"Emo ve Proog, tuhaf makinelerle dolu bir dünyada yol alırken gördükleri şeyler konusunda anlaşamaz. Kısa sorular, yön tarifleri ve tekrarlanan günlük ifadelerle dinleme pratiği yap.","levelNoteTr":"B1, İngilizce altyazı ve kelime desteğiyle dinleme için Lantern English tahminidir; resmî bir CEFR derecesi değildir. Konuşmalar çoğunlukla kısa, yavaş ve tekrarlıdır. Soyut olay örgüsünü yorumlamak ve birkaç mecazı anlamak daha ileri düzeyde olabilir; uzun sessiz sahneler vardır.","advisoryTr":"Karanlık ve gerçeküstü görüntüler, tehdit ve fiziksel şiddet içerir; küçük çocuklar için uygun olmayabilir.","videoUrl":"https://video.blender.org/object-storage/web_videos/cccc3e60-0291-4ecc-aa56-39b2e2c7d0d5-720.mp4","qualities":[{"label":"240p","url":"https://video.blender.org/object-storage/web_videos/cccc3e60-0291-4ecc-aa56-39b2e2c7d0d5-240.mp4","sizeMB":31},{"label":"360p","url":"https://video.blender.org/object-storage/web_videos/cccc3e60-0291-4ecc-aa56-39b2e2c7d0d5-360.mp4","sizeMB":50},{"label":"480p","url":"https://video.blender.org/object-storage/web_videos/cccc3e60-0291-4ecc-aa56-39b2e2c7d0d5-480.mp4","sizeMB":70},{"label":"720p","url":"https://video.blender.org/object-storage/web_videos/cccc3e60-0291-4ecc-aa56-39b2e2c7d0d5-720.mp4","sizeMB":117}],"source":{"name":"Blender Foundation — Elephants Dream","url":"https://orange.blender.org/","license":"CC BY 2.5","licenseUrl":"https://creativecommons.org/licenses/by/2.5/","credit":"(CC) Blender Foundation / Netherlands Media Art Institute | orange.blender.org","licenseSourceUrl":"https://orange.blender.org/blog/creative-commons-license-2/","watchUrl":"https://video.blender.org/videos/watch/cccc3e60-0291-4ecc-aa56-39b2e2c7d0d5","creditNoteTr":"Film, kapanış jeneriğiyle birlikte resmî Blender kaynağından değiştirilmeden oynatılır."},"subtitleSource":{"name":"Wikimedia Commons katkıda bulunanları — İngilizce altyazı","url":"https://commons.wikimedia.org/wiki/TimedText:Elephants_Dream.ogv.en.srt","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","credit":"Wikimedia Commons katkıda bulunanları (yazarlar kaynak sayfasının geçmişinde)","changeNoteTr":"Altyazı sözleri korunmuş; biçim etiketleri kaldırılıp zamanlar saniyeye dönüştürülmüştür. Üç küçük zaman çakışmasının bitişleri en fazla 0,009 saniye kısaltılmıştır."},"glossary":{"emo":"Emo (karakter adı)","proog":"Proog (karakter adı)","snarlers":"hırlayan şeyler; filmde hayalî makine adı","pulp":"posa; burada ezilmiş bir kütle","ground":"ezilmiş, öğütülmüş","sick":"hasta; burada rahatsız, dengesiz","babylon":"Babil","colossus":"dev heykel","rhodes":"Rodos","clockwork":"saat mekanizması; kusursuz işleyiş","hah":"hah! (ünlem)","b":"but kelimesinde kekeleme (ama)","n":"no kelimesinde kekeleme (hayır)"},"captions":[{"start":15,"end":18.13,"text":"At the left we can see…"},{"start":18.13,"end":20.5,"text":"At the right we can see the—"},{"start":20.5,"end":21.98,"text":"…the head-snarlers."},{"start":21.98,"end":24.55,"text":"Everything is safe… Perfectly safe."},{"start":24.55,"end":25.77,"text":"Emo?"},{"start":26.12,"end":27.22,"text":"Emo?"},{"start":28.62,"end":30.104,"text":"Watch out!"},{"start":46.56,"end":48.26,"text":"Are you hurt?"},{"start":51.99,"end":54.2,"text":"I don’t think so. You?"},{"start":55.52,"end":57.09,"text":"I’m OK."},{"start":57.09,"end":61.11,"text":"Get up, Emo! It’s not safe here."},{"start":62.03,"end":63.22,"text":"Let’s go."},{"start":63.22,"end":65.19,"text":"What’s next?"},{"start":65.19,"end":66.96,"text":"You’ll see!"},{"start":67.68,"end":68.84,"text":"You’ll see!"},{"start":76.03,"end":78.48,"text":"Emo! This way."},{"start":94.22999999999999,"end":95.47999999999999,"text":"Follow me!"},{"start":131.1,"end":132.52100000000002,"text":"Hurry, Emo!"},{"start":168.438,"end":170.063,"text":"You’re not paying attention!"},{"start":170.063,"end":174.31,"text":"I–I just want to answer the phone."},{"start":174.31,"end":177.04,"text":"Emo, look… I mean, listen."},{"start":179.14,"end":182,"text":"You have to learn to listen."},{"start":183.14,"end":185.04,"text":"This is not some game."},{"start":185.04,"end":189.18,"text":"You… I mean, we. We could easily die out here."},{"start":190.01,"end":194.39600000000002,"text":"Listen… Listen to the sounds of the machine."},{"start":198.05,"end":200,"text":"Listen to your breathing."},{"start":266.646,"end":269.313,"text":"Well, don’t you ever get tired of this?"},{"start":269.313,"end":271.09,"text":"Tired?!"},{"start":271.09,"end":273.31,"text":"Emo, the machine is like…"},{"start":273.31,"end":275.26,"text":"Like clockwork!"},{"start":275.26,"end":277.063,"text":"One move out of place…"},{"start":277.063,"end":279.12,"text":"…and you’re ground to a pulp."},{"start":280.95,"end":282.104,"text":"But isn’t it—"},{"start":282.104,"end":286.03,"text":"Pulp, Emo! Is that what you want? Pulp?"},{"start":287.104,"end":290.42,"text":"Emo, your goal in life…"},{"start":290.44,"end":291.95,"text":"…pulp?!"},{"start":341.31,"end":343.42,"text":"Emo, close your eyes."},{"start":344.15,"end":345.396,"text":"–Why?\n–Now!"},{"start":351.15,"end":351.97,"text":"OK."},{"start":353.11,"end":354.68,"text":"Good."},{"start":359.42,"end":362.1,"text":"What do you see at your left side, Emo?"},{"start":364.02,"end":366,"text":"–Nothing.\n–Really?"},{"start":366,"end":367.58,"text":"No, nothing at all."},{"start":367.58,"end":371.98,"text":"Really? A–And at your right? What do you see at your right side, Emo?"},{"start":373.31,"end":376.84,"text":"The same, Proog. Exactly the same…"},{"start":376.84,"end":379.896,"text":"–…nothing!\n–Great."},{"start":399.97,"end":402.72,"text":"Listen, Proog! Do you hear that?"},{"start":403.44,"end":404.56,"text":"Can we go here?"},{"start":405.063,"end":406.56,"text":"–There?\n–Yeah!"},{"start":406.58,"end":408.188,"text":"It isn’t safe, Emo."},{"start":409.14,"end":412.01,"text":"–B–But…\n–Trust me, it’s not."},{"start":413.02,"end":414.17,"text":"Well, maybe I could…"},{"start":414.17,"end":415.146,"text":"No."},{"start":417.1,"end":418.82,"text":"–But…\n–No!"},{"start":418.82,"end":420.24,"text":"No!"},{"start":420.771,"end":423.05,"text":"Any further questions, Emo?"},{"start":423.97,"end":425.09,"text":"N–No."},{"start":429.05,"end":430.08,"text":"Emo?"},{"start":431.14,"end":433.08,"text":"Emo, why?!"},{"start":433.08,"end":435.36,"text":"Emo, why…?"},{"start":435.36,"end":438.84,"text":"Why can’t you see the beauty of this place?"},{"start":438.84,"end":440.646,"text":"The way it works."},{"start":440.646,"end":443.92,"text":"How… How perfect it is."},{"start":443.92,"end":447.04,"text":"No, Proog, I don’t see."},{"start":447.04,"end":449.97,"text":"I don’t see because there’s nothing there."},{"start":451.05,"end":455.24,"text":"And why should I trust my life to something that isn’t there?"},{"start":455.24,"end":456.6,"text":"Well, can you tell me that?"},{"start":456.6,"end":457.38,"text":"Emo…"},{"start":457.38,"end":458.92,"text":"Answer me!"},{"start":462.97,"end":464,"text":"Proog…"},{"start":465.05,"end":466.854,"text":"…you’re a sick man!"},{"start":466.854,"end":468.90999999999997,"text":"Stay away from me!"},{"start":472.188,"end":474.854,"text":"No! Emo! It’s a trap!"},{"start":475.42,"end":476.979,"text":"Hah, “it’s a trap!”"},{"start":476.979,"end":481.229,"text":"At the left side you can see the Hanging Gardens of Babylon!"},{"start":481.96,"end":483.95,"text":"How’s that for a trap?"},{"start":485.72,"end":486.92,"text":"No, Emo."},{"start":489,"end":492.64,"text":"At the right side you can see—well guess what…"},{"start":492.64,"end":494.66,"text":"…the Colossus of Rhodes!"},{"start":495.32,"end":496.39,"text":"No!"},{"start":496.396,"end":500.16,"text":"The Colossus of Rhodes! And it is here just for you, Proog."},{"start":500.16,"end":501.688,"text":"Just for you!"},{"start":531,"end":533.021,"text":"It is there…"},{"start":533.021,"end":536.04,"text":"I’m telling you, Emo…"},{"start":537,"end":539.86,"text":"…it is… there…"}]},{"id":"sintel","type":"video","title":"Sintel","creator":"Blender Foundation","year":2010,"level":"B1","durationSeconds":888,"genre":"fantasy","summaryTr":"Sintel, yaralı bir yavru ejderhayla dost olur. Dostunu aramak için çıktığı yolculuk, onu uzak ve tehlikeli topraklara götürür.","levelNoteTr":"B1, Lantern English'in İngilizce altyazı desteğiyle izleme için yaptığı tahmini değerlendirmedir; resmî bir CEFR derecesi değildir. Kısa diyaloglar ve görsel anlatım takibi kolaylaştırır. Bazı fantastik kelimeler ve mecazlar sözlük desteği gerektirebilir.","advisoryTr":"Fantastik çatışma, yaralanma ve ölüm içeren üzücü sahneler bulunur.","videoUrl":"https://video.blender.org/object-storage/web_videos/0eb052d0-fd51-43e6-aa33-ecdbf77a5d40-720.mp4","qualities":[{"label":"240p","url":"https://video.blender.org/object-storage/web_videos/0eb052d0-fd51-43e6-aa33-ecdbf77a5d40-240.mp4","sizeMB":49},{"label":"360p","url":"https://video.blender.org/object-storage/web_videos/0eb052d0-fd51-43e6-aa33-ecdbf77a5d40-360.mp4","sizeMB":84},{"label":"480p","url":"https://video.blender.org/object-storage/web_videos/0eb052d0-fd51-43e6-aa33-ecdbf77a5d40-480.mp4","sizeMB":120},{"label":"720p","url":"https://video.blender.org/object-storage/web_videos/0eb052d0-fd51-43e6-aa33-ecdbf77a5d40-720.mp4","sizeMB":200},{"label":"1080p","url":"https://video.blender.org/object-storage/web_videos/0eb052d0-fd51-43e6-aa33-ecdbf77a5d40-818.mp4","sizeMB":239}],"source":{"name":"Blender Foundation — Sintel / Durian Open Movie Project","url":"https://durian.blender.org/download/","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0/","credit":"© copyright Blender Foundation | durian.blender.org","licenseSourceUrl":"https://durian.blender.org/sharing/","watchUrl":"https://video.blender.org/w/2PcJe5aZqozRvH7MJ8BTmC","creditNoteTr":"Film, sonundaki tam jenerik korunarak resmî Blender kaynağından oynatılır. Film ve İngilizce altyazı metni değiştirilmemiştir; altyazı zamanları site için sayısal biçime dönüştürülmüştür. Türkçe öğrenme açıklamaları Lantern English tarafından hazırlanmıştır."},"subtitleSource":{"name":"Sintel — resmî İngilizce SRT altyazısı","url":"https://durian.blender.org/wp-content/content/subtitles/sintel_en.srt","license":"CC BY 3.0"},"glossary":{"unprepared":"hazırlıksız","scales":"Scales: Sintel'in ejderha dostunun adı (kelime anlamı: pullar)","sintel":"Sintel: filmin ana karakterinin adı","kindred":"benzer duygu ve düşünceleri paylaşan, yakın","spirit":"ruh; burada kindred spirit: ruh ikizi, yakın hissettiğin kişi","gatekeepers":"geçitlerin veya kapıların bekçileri","blade":"bıçak veya kılıcın keskin kısmı","shed":"dökmek; shed blood: kan dökmek","dear":"çok sevilen, değerli","quest":"uzun ve zorlu arayış","shhh":"şşşt, sessiz ol"},"captions":[{"start":107.25,"end":110.5,"text":"This blade has a dark past."},{"start":111.8,"end":115.8,"text":"It has shed much innocent blood."},{"start":118,"end":121.45,"text":"You're a fool for traveling alone,\nso completely unprepared."},{"start":121.75,"end":124.8,"text":"You're lucky your blood's still flowing."},{"start":125.25,"end":126.3,"text":"Thank you."},{"start":127.5,"end":129,"text":"So..."},{"start":129.4,"end":133.8,"text":"What brings you to\nthe land of the gatekeepers?"},{"start":135,"end":137.5,"text":"I'm searching for someone."},{"start":138,"end":142.2,"text":"Someone very dear?\nA kindred spirit?"},{"start":143.4,"end":145,"text":"A dragon."},{"start":148.85,"end":151.75,"text":"A dangerous quest for a lone hunter."},{"start":152.95,"end":155.87,"text":"I've been alone for\nas long as I can remember."},{"start":207.25,"end":210.5,"text":"We're almost done. Shhh..."},{"start":210.75,"end":213.5,"text":"Hey, sit still."},{"start":228.25,"end":232.25,"text":"Good night, Scales."},{"start":250.35,"end":253.85,"text":"Get him, Scales! Come on!"},{"start":265.25,"end":268.25,"text":"Scales?"},{"start":304,"end":307.5,"text":"Yeah! Come on!"},{"start":338.75,"end":342,"text":"Scales!"},{"start":445.85,"end":447.5,"text":"I have failed."},{"start":452.8,"end":456.5,"text":"You've only failed to see..."},{"start":457.8,"end":460.5,"text":"These are dragon lands, Sintel."},{"start":460.85,"end":464,"text":"You are closer than you know."},{"start":557.6,"end":559.5,"text":"Scales!"},{"start":621.6,"end":624,"text":"Scales?"},{"start":626.2,"end":629.8,"text":"Scales..."}]},{"id":"tears-of-steel","type":"video","title":"Tears of Steel","creator":"Blender Foundation","year":2012,"level":"B1","durationSeconds":734,"genre":"scifi","summaryTr":"Bir bilim kurgu çekim platosunda eski bir aşkın hesaplaşması, robotlar ve zamana karşı yarış iç içe geçer. Konuşmalar günlük dilde ve sahne sahne ilerler.","levelNoteTr":"B1, Lantern English'in İngilizce altyazı desteğiyle izleme için yaptığı tahmini değerlendirmedir; resmî bir CEFR derecesi değildir. Konuşmalar günlük dildedir; birkaç argo ve sinema terimi (ad-lib, abort, cut) sözlük desteği gerektirebilir. Sintel'e göre konuşma daha yoğundur ve daha uzun diyaloglar içerir.","advisoryTr":"Bilim kurgu aksiyonu ve robot saldırısı sahneleri vardır. Konuşmalarda hafif argo ve küfür geçer.","videoUrl":"https://video.blender.org/object-storage/web_videos/8533ea43-4271-4a57-9694-e9d0b35e1aa1-720.mp4","qualities":[{"label":"240p","url":"https://video.blender.org/object-storage/web_videos/8533ea43-4271-4a57-9694-e9d0b35e1aa1-240.mp4","sizeMB":50},{"label":"360p","url":"https://video.blender.org/object-storage/web_videos/8533ea43-4271-4a57-9694-e9d0b35e1aa1-360.mp4","sizeMB":86},{"label":"480p","url":"https://video.blender.org/object-storage/web_videos/8533ea43-4271-4a57-9694-e9d0b35e1aa1-480.mp4","sizeMB":122},{"label":"720p","url":"https://video.blender.org/object-storage/web_videos/8533ea43-4271-4a57-9694-e9d0b35e1aa1-720.mp4","sizeMB":225},{"label":"1080p","url":"https://video.blender.org/object-storage/web_videos/8533ea43-4271-4a57-9694-e9d0b35e1aa1-800.mp4","sizeMB":248}],"source":{"name":"Blender Foundation — Tears of Steel / Mango Open Movie Project","url":"https://mango.blender.org/","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0/","credit":"(CC) Blender Foundation | mango.blender.org","licenseSourceUrl":"https://mango.blender.org/sharing/","watchUrl":"https://video.blender.org/videos/watch/8533ea43-4271-4a57-9694-e9d0b35e1aa1","creditNoteTr":"Film, kapanış jeneriğiyle birlikte resmî Blender kaynağından oynatılır. Film ve İngilizce altyazı metni değiştirilmemiştir; altyazı zamanları site için sayısal biçime dönüştürülmüştür. Türkçe öğrenme açıklamaları Lantern English tarafından hazırlanmıştır."},"subtitleSource":{"name":"Tears of Steel — resmî İngilizce SRT altyazısı (TOS-en.srt)","url":"https://download.blender.org/demo/movies/ToS/subtitles/TOS-en.srt","license":"CC BY 3.0"},"glossary":{"jerk":"aşağılık herif, hıyar","passions":"tutkular","robotics":"robot bilimi, robotik","freaked":"korkmuş, tedirgin olmuş (freak out)","freaky":"ürkütücü, tuhaf","claws":"pençeler","synced":"senkronize edildi","overwrite":"üzerine yazma","abort":"iptal etmek, yarıda kesmek","tender":"nazik, şefkatli","crush":"ezmek, ezip geçmek","rockstar":"rock yıldızı; çok başarılı kişi","vivacissimo":"müzik terimi: çok canlı ve hızlı","captain":"kaptan"},"captions":[{"start":23,"end":24.5,"text":"You're a jerk, Thom."},{"start":25,"end":27,"text":"Look Celia, we have to follow our passions;"},{"start":27,"end":30.5,"text":"...you have your robotics, and I\njust want to be awesome in space."},{"start":30.8,"end":34,"text":"Why don't you just admit that\nyou're freaked out by my robot hand?"},{"start":34.5,"end":36,"text":"I'm not freaked out by- it's..."},{"start":37,"end":38,"text":"...alright! Fine!"},{"start":38,"end":41,"text":"I'm freaked out! I have nightmares\nthat I'm being chased..."},{"start":41,"end":42,"text":"...by these giant robotic claws of death..."},{"start":42.2,"end":45,"text":"\"Fourty years later\"\nWhatever, Thom. We're done."},{"start":50,"end":53.5,"text":"Robot's memory synced and locked!"},{"start":61,"end":63,"text":"This is pretty freaky."},{"start":117,"end":119,"text":"Shouldn't you be down there?"},{"start":131,"end":133,"text":"I heard you guys talking last night."},{"start":136,"end":138,"text":"It's not my fault, you know."},{"start":191,"end":192,"text":"Are you ready?"},{"start":193,"end":195,"text":"Of course you're ready, you're a rockstar."},{"start":197,"end":198,"text":"How's it looking, Barley?"},{"start":199,"end":201,"text":"We should have about ten minutes..."},{"start":201.5,"end":203,"text":"Well that's perfect."},{"start":203.5,"end":206.5,"text":"We're on in one! All systems go!\nYeah you, go!"},{"start":208,"end":212,"text":"Go! Move your asses! Go go go!"},{"start":213,"end":217,"text":"I love it! Come on, go!"},{"start":223,"end":224,"text":"That's nice."},{"start":224.5,"end":225.7,"text":"Nothing to worry about."},{"start":226,"end":227,"text":"Thom."},{"start":231,"end":233,"text":"There she is."},{"start":233.5,"end":234.5,"text":"Now."},{"start":235,"end":236,"text":"You love her."},{"start":237,"end":238.5,"text":"She is your passion!"},{"start":240,"end":241,"text":"Be tender to her."},{"start":241.5,"end":244.5,"text":"Be honest! Eh- be tender."},{"start":245,"end":248,"text":"Remind her what love is."},{"start":292,"end":295,"text":"...and, action!"},{"start":296.5,"end":298,"text":"Memory overwrite in progress!"},{"start":299,"end":301,"text":"You're a jerk, Thom!"},{"start":302.5,"end":305,"text":"Ohp- Sorry! Sorry."},{"start":316,"end":317,"text":"Look Celia."},{"start":318,"end":320,"text":"We have to follow our passions."},{"start":321,"end":323,"text":"You have your robotics..."},{"start":325,"end":328,"text":"...and I just want to be awesome in space."},{"start":339,"end":341,"text":"Okay, they're coming. Two minutes left!"},{"start":343,"end":344,"text":"Speed it up, Thom!"},{"start":345,"end":346,"text":"Vivacissimo!"},{"start":347,"end":350,"text":"Why don't you just admit that you're\nfreaked out by my robot hand?"},{"start":356,"end":359,"text":"Listen Celia, I was young..."},{"start":359.5,"end":361,"text":"...and a dick."},{"start":361,"end":363,"text":"But that's no reason to\ndestroy the world."},{"start":365,"end":366,"text":"Why does he do this?"},{"start":366.5,"end":368.5,"text":"We already tried that one!"},{"start":371.5,"end":372.5,"text":"Abort!"},{"start":373,"end":374,"text":"Cut!"},{"start":374,"end":375,"text":"Whoaaa!"},{"start":379,"end":380,"text":"Whoaaa!"},{"start":381,"end":383,"text":"Nooooo!"},{"start":383,"end":385,"text":"You broke my heart."},{"start":386,"end":387,"text":"I know."},{"start":387,"end":389,"text":"You forgot me on earth."},{"start":389,"end":390,"text":"I know."},{"start":390.5,"end":393,"text":"I should just crush you."},{"start":396,"end":397,"text":"I'm-"},{"start":407,"end":408,"text":"I'm sorry."},{"start":410,"end":411,"text":"Good ad-lib."},{"start":419,"end":420.5,"text":"Not my fault!"},{"start":422,"end":423,"text":"This time."},{"start":428,"end":429.5,"text":"Quiet on set!"},{"start":430,"end":431,"text":"We're out of time!"},{"start":493,"end":494,"text":"Come on!"},{"start":502,"end":504,"text":"RAAAAAAAAH!"},{"start":504,"end":505,"text":"Memory overwrite, 90%."},{"start":506,"end":508,"text":"Captain! We have to abort!"},{"start":518,"end":520,"text":"The world's changed, Celia..."},{"start":534,"end":536,"text":"...maybe we can too."},{"start":538,"end":539,"text":"Memory overwrite complete!"},{"start":559,"end":560,"text":"You know."},{"start":562,"end":564,"text":"There's a lesson to be learned from this."},{"start":566,"end":567,"text":"Could'a gone worse."}]},{"id":"cosmos-laundromat","type":"video","title":"Cosmos Laundromat: First Cycle","creator":"Blender Foundation","year":2015,"level":"B2","durationSeconds":730,"genre":"fantasy","summaryTr":"Issız bir adada yaşayan Franck, hayatını değiştirebileceğini söyleyen sıra dışı bir satıcıyla karşılaşır. İmalı konuşmaları, ikna dilini ve günlük deyimleri takip et.","levelNoteTr":"B2, İngilizce altyazı desteğiyle dinleme için Lantern English tahminidir; resmî bir CEFR derecesi değildir. Günlük ifadelerin yanında ima, alay, mecaz ve satış konuşması vardır. Aksanlar, eksiltili cümleler ve birkaç teknik ifade dinlemeyi zorlaştırır; ilk konuşma yaklaşık 2:20’de başlar.","advisoryTr":"İntihar düşüncesi ve girişimi, ağır küfür ve karanlık temalar içerir. Hassas izleyiciler için uygun olmayabilir; yapımcı hedef kitleyi 13+ olarak belirtir.","videoUrl":"https://video.blender.org/object-storage/web_videos/f507dfdc-e73e-45a4-9778-d758cbe1ce96-720.mp4","qualities":[{"label":"240p","url":"https://video.blender.org/object-storage/web_videos/f507dfdc-e73e-45a4-9778-d758cbe1ce96-240.mp4","sizeMB":43},{"label":"360p","url":"https://video.blender.org/object-storage/web_videos/f507dfdc-e73e-45a4-9778-d758cbe1ce96-360.mp4","sizeMB":76},{"label":"480p","url":"https://video.blender.org/object-storage/web_videos/f507dfdc-e73e-45a4-9778-d758cbe1ce96-480.mp4","sizeMB":110},{"label":"720p","url":"https://video.blender.org/object-storage/web_videos/f507dfdc-e73e-45a4-9778-d758cbe1ce96-720.mp4","sizeMB":201},{"label":"1080p","url":"https://video.blender.org/object-storage/web_videos/f507dfdc-e73e-45a4-9778-d758cbe1ce96-804.mp4","sizeMB":230}],"source":{"name":"Blender Foundation — Cosmos Laundromat: First Cycle","url":"https://gooseberry.blender.org/","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0/","credit":"(CC) Blender Foundation | gooseberry.blender.org","licenseSourceUrl":"https://gooseberry.blender.org/license/","watchUrl":"https://video.blender.org/videos/watch/f507dfdc-e73e-45a4-9778-d758cbe1ce96","creditNoteTr":"Film, kapanış jeneriğiyle birlikte resmî Blender kaynağından değiştirilmeden oynatılır."},"subtitleSource":{"name":"Wikimedia Commons katkıda bulunanları — İngilizce altyazı","url":"https://commons.wikimedia.org/wiki/TimedText:Cosmos_Laundromat_-_First_Cycle_-_Official_Blender_Foundation_release.webm.en-gb.srt","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","credit":"Wikimedia Commons katkıda bulunanları (yazarlar kaynak sayfasının geçmişinde)","changeNoteTr":"Altyazı sözleri korunmuş; biçim etiketleri kaldırılıp zamanlar saniyeye dönüştürülmüştür."},"glossary":{"franck":"Franck (karakter adı)","victor":"Victor (karakter adı)","hector":"Hector (yanlış söylenen ad)","casper":"Casper (yanlış söylenen ad)","hooves":"toynaklar","sheepy":"koyuna ait; burada koyunluk işleri","fucking":"lanet olası (ağır küfür)","tumble":"tamburda döndürme","spin":"sıkma, dönme","variable":"değişken, ayarlanabilir","squeaky":"gıcırdayan; squeaky clean: tertemiz","hehehe":"he he he (gülme sesi)","eh":"ee, hey (ünlem)","ho":"hop, hey (ünlem)","err":"ee, şey (duraksama)"},"captions":[{"start":140,"end":141.3,"text":"Excuse me?"},{"start":141.8,"end":143,"text":"Excuse me, sir?"},{"start":144,"end":145.5,"text":"Excuse me?"},{"start":147,"end":149,"text":"Oh, come on."},{"start":150,"end":152,"text":"Do you have a moment, sir?"},{"start":152,"end":157.05,"text":"I'm kind of in the middle of something here."},{"start":157.05,"end":158.95,"text":"I've come a long way for you, Franck."},{"start":169,"end":171,"text":"My name is Victor."},{"start":172,"end":174,"text":"Hi."},{"start":174,"end":176,"text":"And you are...."},{"start":178,"end":179.5,"text":"You are Franck."},{"start":180.5,"end":184,"text":"You are so much more than just a sheep, aren't you?"},{"start":185,"end":188,"text":"Oh yeah? How would you know?"},{"start":190,"end":192.9,"text":"Look at you. You're an adventurer, Franck."},{"start":192.9,"end":197,"text":"Just like me, you're... a lone wolf."},{"start":198,"end":202,"text":"Tell me, does one choose to be alone?"},{"start":203,"end":205,"text":"No, one doesn't."},{"start":205,"end":207.6,"text":"One doesn’t even choose to be a wolf."},{"start":210,"end":212,"text":"Or does one?"},{"start":215,"end":218.8,"text":"Well, mister... err... Hector."},{"start":218.8,"end":220,"text":"Victor. Victor."},{"start":220,"end":226,"text":"I don’t know what you’re on about but I'm just"},{"start":226,"end":228.6,"text":"And I suggest you do the same."},{"start":228.6,"end":232,"text":"No. No no no, Franck. Wait wait wait."},{"start":232,"end":235,"text":"No. This is not... the way."},{"start":235,"end":238.5,"text":"Just give me one minute of your precious time."},{"start":238.5,"end":241.5,"text":"Precious time? Hehehe."},{"start":241.5,"end":243.5,"text":"Yeah just give me one minute."},{"start":243.5,"end":246.5,"text":"You would have one more minute, wouldn't you?"},{"start":248,"end":251,"text":"Okay half. Half a minute."},{"start":265.1,"end":269.3,"text":"I knew it."},{"start":269.3,"end":272,"text":"You will not regret this."},{"start":272,"end":275,"text":"The adventures you will have."},{"start":275,"end":278.5,"text":"All the lives you've ever wanted."},{"start":278.5,"end":281.7,"text":"All you’ve been missing."},{"start":281.7,"end":286,"text":"Here. This is... the best product we have... in store."},{"start":286,"end":290,"text":"Variable spin speed, excellent tumble performance..."},{"start":290,"end":294,"text":"...in one... handy... device. Squeaky clean."},{"start":297,"end":301,"text":"Well this... this better be good."},{"start":301,"end":304,"text":"Took me ages to tie that rope."},{"start":305,"end":307,"text":"With my fucking hooves."},{"start":307,"end":309,"text":"No more need for hooves."},{"start":309,"end":311,"text":"No more sheepy business."},{"start":312,"end":314.5,"text":"Ho! Time flies."},{"start":314.5,"end":316.7,"text":"Wait wait wait wait wait wait."},{"start":316.7,"end":318.5,"text":"How does this thing work?"},{"start":318.5,"end":321,"text":"I mean, how do I make it work?"},{"start":321,"end":322.5,"text":"No you don't."},{"start":322.5,"end":324,"text":"I just turned it on for you."},{"start":326,"end":327,"text":"When can I go?"},{"start":329,"end":330,"text":"Where can I go?"},{"start":330,"end":333,"text":"We will pick you up. Don't worry, just stay here."},{"start":333,"end":335,"text":"In this exact place."},{"start":335,"end":337,"text":"Don't move. Just wait."},{"start":338,"end":340,"text":"That's it?"},{"start":341,"end":342,"text":"Hey!"},{"start":342.5,"end":344,"text":"Hey!"},{"start":344,"end":345.5,"text":"Wait, mister!"},{"start":345.5,"end":348.9,"text":"Eh, Casper!"},{"start":348.9,"end":351,"text":"Hector whatever!"}]},{"id":"sprite-fright","type":"video","title":"Sprite Fright","creator":"Blender Foundation","year":2021,"level":"B2","durationSeconds":630,"genre":"horror","summaryTr":"Doğa gezisine çıkan bir öğrenci grubu, ormanın küçük sakinleriyle karşılaşır. İngiliz aksanları, hızlı grup konuşmaları ve kelime oyunları içeren bir korku komedisi.","levelNoteTr":"B2, İngilizce altyazı desteğiyle dinleme için Lantern English tahminidir; resmî bir CEFR derecesi değildir. Hızlı İngiliz İngilizcesi, argo, kısaltılmış söyleyişler ve kelime oyunları vardır. Latince tür adları ve doğa terimleri kelime desteği gerektirebilir.","advisoryTr":"Kanlı çizgi film şiddeti, ölüm, korku sahneleri, zorbalık, alkol ve ağır argo/küfür içerir. Yapımcı 13+ olarak belirtir; küçük çocuklar için uygun değildir.","videoUrl":"https://video.blender.org/object-storage/web_videos/a69d68a5-a0e0-4a80-9d66-49f093c97aaf-720.mp4","qualities":[{"label":"720p","url":"https://video.blender.org/object-storage/web_videos/a69d68a5-a0e0-4a80-9d66-49f093c97aaf-720.mp4","sizeMB":102},{"label":"1080p","url":"https://video.blender.org/object-storage/web_videos/a69d68a5-a0e0-4a80-9d66-49f093c97aaf-804.mp4","sizeMB":111}],"source":{"name":"Blender Foundation — Sprite Fright","url":"https://studio.blender.org/projects/sprite-fright/","license":"CC BY 1.0","licenseUrl":"https://creativecommons.org/licenses/by/1.0/","credit":"(CC) Blender Foundation | studio.blender.org","licenseSourceUrl":"https://studio.blender.org/projects/sprite-fright/pages/about/","watchUrl":"https://video.blender.org/videos/watch/a69d68a5-a0e0-4a80-9d66-49f093c97aaf","creditNoteTr":"Film, kapanış jeneriğiyle birlikte resmî Blender kaynağından değiştirilmeden oynatılır."},"subtitleSource":{"name":"Blender Studio — resmî İngilizce WebVTT altyazısı","url":"https://video.blender.org/object-storage/captions/541aac20-a387-4d4b-be46-fd722b33fe58-en.vtt","license":"CC BY 1.0","licenseUrl":"https://creativecommons.org/licenses/by/1.0/","changeNoteTr":"Altyazı sözleri korunmuş; biçim etiketleri kaldırılıp zamanlar saniyeye dönüştürülmüştür."},"glossary":{"cornu":"Cornu aspersum: bir kara salyangozu türü","aspersum":"Cornu aspersum: bir kara salyangozu türü","motacilla":"Motacilla flava: sarı kuyruksallayan kuşu","flava":"Motacilla flava: sarı kuyruksallayan kuşu","fungis":"mantarlar; fun guys (eğlenceli tipler) kelime oyunu","dorkwad":"aptal, ezik (aşağılayıcı argo)","innit":"öyle değil mi? (isn’t it, İngiliz argosu)","oy":"hey! (seslenme)","phil":"Phil (karakter adı)","bbq":"barbekü, mangal","piss":"işemek (kaba); piss break: tuvalet molası","shagged":"cinsel ilişkiye girmiş (kaba argo)","sprite":"orman perisi; burada yaratıkların adı/kelime oyunu","sprites":"orman perileri; filmdeki yaratıklar","psycho":"psikopat, kaçık (argo)","bitches":"sürtükler (ağır hakaret)","bastards":"alçaklar (ağır hakaret)","geezer":"herif, adam (İngiliz argosu)","weenie":"ödlek, pısırık (argo)","wagtail":"kuyruksallayan kuşu","ribbing":"takılma, alay etme","wasted":"sarhoş, kafası iyi (argo)","buns":"çörekler; Sugar Buns: tatlım (hitap)","cakes":"kekler; Sweet cakes: tatlım (hitap)","muffin":"muffin; Love muffin: sevgilim (hitap)","punks":"serseriler","aaaah":"aaa! (çığlık)","nuh":"hayır (nuh-uh: olumsuzluk ünlemi)","uh":"ee (duraksama)","mtv":"MTV (müzik televizyon kanalı)","c'mon":"haydi, hadi (come on)","dilly":"dilly-dally: oyalanmak","outta":"out of: içinden, dışarı (konuşma dili)"},"captions":[{"start":17.375,"end":19.458,"text":"Hello, Mr.Snail!"},{"start":19.458,"end":22.333,"text":"Aw, you cute little cornu aspersum."},{"start":22.333,"end":25.125,"text":"Latin name bonus-points!"},{"start":28.375,"end":30.833,"text":"Can’t believe we got stuck with the tree hugger."},{"start":30.833,"end":34.667,"text":"If I have to hear the latin name for one more animal, I swear I'm gonna kill her."},{"start":34.667,"end":39.542,"text":"Relax, Sugar Buns. While she does all the work we’ll have all the fun."},{"start":39.542,"end":42.583,"text":"Yeah! And get wasted out of our minds!"},{"start":42.583,"end":44.25,"text":"Way ahead of you, man."},{"start":44.25,"end":48.625,"text":"C’mon, team! We mustn’t dilly-dally when there’s so much nature to see!"},{"start":48.625,"end":53.667,"text":"I was thinking we should call our class project, “Fungis in a Forest!”"},{"start":53.667,"end":56.167,"text":"Get it? Because we’re a group of fun guys."},{"start":56.167,"end":57.667,"text":"And also fungis which-"},{"start":57.667,"end":62.458,"text":"Shush! That’s a yellow wagtail. And she’s in distress!"},{"start":62.75,"end":66.333,"text":"There, there, my little motacilla flava."},{"start":67.792,"end":70.042,"text":"Oh! Look at her go!"},{"start":70.375,"end":71.5,"text":"Wow!"},{"start":71.5,"end":74.417,"text":"Out of the way, dorkwad! We're camping here."},{"start":74.417,"end":77.5,"text":"Finally! Time to get that BBQ burning."},{"start":78.417,"end":80.167,"text":"Oh. Oh, dear."},{"start":87.333,"end":88.875,"text":"Gross!"},{"start":90.833,"end":95.458,"text":"Oh. Easy, guys. We’re supposed to be studying nature, not wrecking it."},{"start":95.458,"end":97.958,"text":"Piss break!"},{"start":100.708,"end":104.667,"text":"Oy, fungus freak! Make yourself useful and fix the tent."},{"start":104.667,"end":108.917,"text":"Oh, a bit of friendly campsite ribbing. Fun."},{"start":109.875,"end":112.583,"text":"She wouldn't survive 5 minutes alone in these woods."},{"start":112.583,"end":116.792,"text":"Yeah. She's a real weenie that one, innit?"},{"start":116.792,"end":119,"text":"Oy, Phil! How those sausages coming?"},{"start":119,"end":122.458,"text":"Almost ready! Just need a bit more salt..."},{"start":156.333,"end":159.208,"text":"It's incredible. It's a new species."},{"start":159.208,"end":161.875,"text":"What the bloody hell are those things?"},{"start":161.875,"end":164.542,"text":"It's like a gnome shagged a mushroom."},{"start":177.375,"end":179.583,"text":"They’re absolutely adorable."},{"start":179.583,"end":182,"text":"Yeah, absolutely bloody adorable."},{"start":182,"end":185.625,"text":"And I bet we’ll make a fortune if we catch one of those things."},{"start":185.625,"end":186.958,"text":"We'd be famous!"},{"start":186.958,"end":188.292,"text":"Get on MTV."},{"start":188.292,"end":189.875,"text":"I wonder what they taste like."},{"start":189.875,"end":192.5,"text":"We really shouldn't disrupt their habitat."},{"start":192.5,"end":195.917,"text":"Right. Sure, sure."},{"start":195.917,"end":197.5,"text":"Greetings."},{"start":197.5,"end":199,"text":"Welcome, friends."},{"start":199,"end":201.208,"text":"I'll be right down."},{"start":206.25,"end":208.75,"text":"Could I interest you in some peppermint tea?"},{"start":208.75,"end":210.667,"text":"What are you guys?"},{"start":210.667,"end":214.417,"text":"We are Sprites. We sprite balance to the forest."},{"start":214.417,"end":219.667,"text":"We take care of the animals, plants, birds, moss..."},{"start":221,"end":223.917,"text":"Guys? Guys, I..."},{"start":226.583,"end":231.542,"text":"Hey, uh, little mushroom geezer, you cool with us camping here for the night?"},{"start":231.542,"end":236.333,"text":"Absolutely. A friend of the forest is a friend of the sprites."},{"start":237.708,"end":241.375,"text":"Maybe it was just ketchup... or something... like..."},{"start":241.375,"end":249.125,"text":"Red paint? Yeah, maybe they were just painting their little hats or... something..."},{"start":255.5,"end":257.04200000000003,"text":"Guys?"},{"start":260.08299999999997,"end":261.625,"text":"Guys?"},{"start":262.41700000000003,"end":263.95799999999997,"text":"Guys, this isn't funny."},{"start":265.08299999999997,"end":266.625,"text":"Guys?"},{"start":287.20799999999997,"end":290.16700000000003,"text":"We were just gonna catch one! But they’re psycho!"},{"start":290.16700000000003,"end":292.95799999999997,"text":"You gotta get me outta these! Hurry! They’re gonna kill us!"},{"start":295.66700000000003,"end":296.58299999999997,"text":"Hurry!"},{"start":296.58299999999997,"end":299.45799999999997,"text":"Right foot, left foot, leaf and stone."},{"start":299.45799999999997,"end":303.583,"text":"You picked the wrong camping spot, bitches."},{"start":303.583,"end":305.292,"text":"Sprite them!"},{"start":305.833,"end":307.542,"text":"Run!!!"},{"start":330.25,"end":332.08299999999997,"text":"Aaaah! My eyes!"},{"start":357.625,"end":359.625,"text":"Sugar Buns?! Help me!"},{"start":367.125,"end":368.875,"text":"Sweet cakes!"},{"start":371.292,"end":373.208,"text":"Love muffin..."},{"start":374.167,"end":375.667,"text":"Huh?"},{"start":400.04200000000003,"end":403.45799999999997,"text":"No, no, no! I can’t swim!"},{"start":415.08299999999997,"end":416.875,"text":"Yes!"},{"start":418.29200000000003,"end":419.70799999999997,"text":"No!"},{"start":432.833,"end":436.20799999999997,"text":"I don’t want to hurt you! Just keep your distance!"},{"start":437.20799999999997,"end":441.125,"text":"All right, then. Eat salt, you little green bastards!"},{"start":476.83299999999997,"end":478.54200000000003,"text":"Nuh-uh-uh."},{"start":478.54200000000003,"end":483.333,"text":"Those punks treated the world as their own personal rubbish bin."},{"start":483.333,"end":485.625,"text":"And you set them free!"},{"start":485.625,"end":487.833,"text":"Now you'll join them!"},{"start":525.875,"end":529.167,"text":"I’ll give you that one, Brother Bird!"},{"start":530,"end":535.417,"text":"Alright sprites, let’s burn the bodies and have some peppermint tea."}]}];
